/* @lc app=leetcode id=2508 lang=kotlin */ class Solution { fun isPossible(n: Int, edges: List<List<Int>>): Boolean = Array(n + 1) { mutableSetOf<Int>() }.also { adj -> edges.forEach { adj[it[0]].add(it[1]).also { _ -> adj[it[1]].add(it[0]) } } }.let { adj -> (1..n).filter { adj[it].size % 2 != 0 }.let { odd -> if (odd.isEmpty()) true else if (odd.size == 2) (!adj[odd[0]].contains(odd[1]) || (1..n).any { i -> i != odd[0] && i != odd[1] && !adj[odd[0]].contains(i) && !adj[odd[1]].contains(i) }) else if (odd.size == 4) ( (!adj[odd[0]].contains(odd[1]) && !adj[odd[2]].contains(odd[3])) || (!adj[odd[0]].contains(odd[2]) && !adj[odd[1]].contains(odd[3])) || (!adj[odd[0]].contains(odd[3]) && !adj[odd[1]].contains(odd[2])) ) else false } } }